function phaseMetrics(){
  const p=effectiveP();
  return PHASEORDER.map(ph=>{
    const rounds=ROUNDS[ph], info=INFO[ph];
    const winProb=Math.pow(p,rounds);
    const payout=1/(winProb+BET.fee);
    const value=info*Math.min(1,(1/winProb-1)/5);
    return {ph,rounds,info,winProb,payout,value};
  });
}

