def load_openrouter_key():
    """OpenRouter key, server-side only. config.json wins; else read the same
    source MapSnap uses (Maia's DB) so WC2026 shares the one key."""
    k = (CFG.get("openrouter_api_key") or "").strip()
    if k:
        return k
    for db in [r"C:\APPS\QI\maia.db"]:
        try:
            row = sqlite3.connect(db).execute(
                "SELECT value FROM config WHERE key='system.openrouter_api_key'").fetchone()
            if row and row[0]:
                return row[0].strip()
        except Exception:
            pass
    return ""

@app.post("/config")
async def post_config(request: Request):
    """Write config.json — LOCAL ONLY. Reloads settings live (the port still needs a restart)."""
    if _via_tunnel(request):
        return JSONResponse({"error": "Config editing is local-only."}, status_code=403)
    data = await request.json()
    json.dump(data, open(CFG_PATH, "w", encoding="utf-8"), indent=2, ensure_ascii=False)
    global CFG          # apply most settings live (refresh reads CFG.get(...) on each cycle)
    CFG = load_cfg()
    return {"ok": True, "saved": CFG_PATH}
